CREATE SCHEMA IF NOT EXISTS ops;
CREATE SCHEMA IF NOT EXISTS erp;
CREATE TABLE IF NOT EXISTS ops.schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ops.users(id uuid PRIMARY KEY,username text UNIQUE NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('viewer','operator','purchasing','production_manager','quality_manager','admin')));
CREATE TABLE ops.scopes(id uuid PRIMARY KEY,name text NOT NULL,synthetic boolean NOT NULL DEFAULT true CHECK(synthetic),owner_id uuid REFERENCES ops.users(id),clock_at timestamptz NOT NULL,erp_revision integer NOT NULL DEFAULT 1 CHECK(erp_revision>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ops.memberships(scope_id uuid REFERENCES ops.scopes(id),user_id uuid REFERENCES ops.users(id),PRIMARY KEY(scope_id,user_id));
CREATE TABLE ops.sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES ops.users(id),csrf_hash text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE ops.source_events(id uuid PRIMARY KEY,scope_id uuid NOT NULL REFERENCES ops.scopes(id),source text NOT NULL CHECK(source IN ('EMAIL','API','FORM')),source_account_id text NOT NULL,source_id text NOT NULL,payload_hash text NOT NULL,envelope jsonb NOT NULL,authenticated boolean NOT NULL DEFAULT true,status text NOT NULL DEFAULT 'RECEIVED',review_reasons jsonb NOT NULL DEFAULT '[]',received_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_id,id),UNIQUE(scope_id,source,source_account_id,source_id));
CREATE TABLE ops.incidents(id uuid PRIMARY KEY,scope_id uuid NOT NULL REFERENCES ops.scopes(id),number text NOT NULL,incident_type text NOT NULL,business_key text NOT NULL,title text NOT NULL,status text NOT NULL CHECK(status IN ('NEW','ANALYZING','ASSESSED','WAITING_APPROVAL','ACTION_IN_PROGRESS','MONITORING','MANUAL_REVIEW','RESOLVED','CLOSED')),revision integer NOT NULL DEFAULT 1,risk_score integer CHECK(risk_score BETWEEN 0 AND 100),severity text,affected_open_order_value_cents bigint NOT NULL DEFAULT 0,current_impact_id uuid,prior_incident_id uuid,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_id,id),UNIQUE(scope_id,number));
CREATE UNIQUE INDEX active_incident ON ops.incidents(scope_id,incident_type,business_key) WHERE status NOT IN ('RESOLVED','CLOSED');
CREATE TABLE ops.incident_revisions(id uuid PRIMARY KEY,scope_id uuid NOT NULL,incident_id uuid NOT NULL,revision integer NOT NULL,fingerprint text NOT NULL,facts jsonb NOT NULL,evidence jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(scope_id,incident_id) REFERENCES ops.incidents(scope_id,id) ON DELETE CASCADE,UNIQUE(scope_id,incident_id,revision),UNIQUE(scope_id,id));
CREATE TABLE ops.incident_sources(scope_id uuid NOT NULL,incident_id uuid NOT NULL,source_event_id uuid NOT NULL,revision integer NOT NULL,PRIMARY KEY(scope_id,incident_id,source_event_id),FOREIGN KEY(scope_id,incident_id,revision) REFERENCES ops.incident_revisions(scope_id,incident_id,revision) ON DELETE CASCADE,FOREIGN KEY(scope_id,source_event_id) REFERENCES ops.source_events(scope_id,id) ON DELETE CASCADE);
CREATE TABLE ops.analysis_jobs(id uuid PRIMARY KEY,scope_id uuid NOT NULL,source_event_id uuid NOT NULL,correlation_id uuid NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','RUNNING','RETRY_SCHEDULED','SUCCEEDED','DEAD_LETTER')),step text NOT NULL DEFAULT 'NORMALIZE',attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 4),claim_token uuid,lease_until timestamptz,owner text,execution_id text,workflow_id text,next_attempt_at timestamptz NOT NULL DEFAULT now(),result jsonb NOT NULL DEFAULT '{}',last_error text,FOREIGN KEY(scope_id,source_event_id) REFERENCES ops.source_events(scope_id,id) ON DELETE CASCADE,UNIQUE(scope_id,source_event_id),UNIQUE(scope_id,id));
CREATE INDEX job_due ON ops.analysis_jobs(status,next_attempt_at,lease_until);
CREATE TABLE erp.snapshots(id uuid PRIMARY KEY,scope_id uuid NOT NULL REFERENCES ops.scopes(id),erp_revision integer NOT NULL,incident_type text NOT NULL,body jsonb NOT NULL,content_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_id,id));
CREATE TABLE ops.impact_assessments(id uuid PRIMARY KEY,scope_id uuid NOT NULL,incident_id uuid NOT NULL,revision integer NOT NULL,snapshot_id uuid NOT NULL,method_version text NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(scope_id,incident_id,revision) REFERENCES ops.incident_revisions(scope_id,incident_id,revision) ON DELETE CASCADE,FOREIGN KEY(scope_id,snapshot_id) REFERENCES erp.snapshots(scope_id,id),UNIQUE(scope_id,incident_id,revision),UNIQUE(scope_id,id));
CREATE TABLE ops.incident_impacts(scope_id uuid NOT NULL,impact_id uuid NOT NULL,sales_line_id text NOT NULL,value_cents bigint NOT NULL CHECK(value_cents>=0),PRIMARY KEY(scope_id,impact_id,sales_line_id),FOREIGN KEY(scope_id,impact_id) REFERENCES ops.impact_assessments(scope_id,id) ON DELETE CASCADE);
CREATE TABLE ops.risk_assessments(id uuid PRIMARY KEY,scope_id uuid NOT NULL,impact_id uuid NOT NULL,policy_version text NOT NULL,body jsonb NOT NULL,FOREIGN KEY(scope_id,impact_id) REFERENCES ops.impact_assessments(scope_id,id) ON DELETE CASCADE,UNIQUE(scope_id,impact_id));
CREATE TABLE ops.action_plans(id uuid PRIMARY KEY,scope_id uuid NOT NULL,incident_id uuid NOT NULL,revision integer NOT NULL,impact_assessment_id uuid NOT NULL,plan_version integer NOT NULL,plan_hash text NOT NULL,policy_version text NOT NULL,body jsonb NOT NULL,status text NOT NULL DEFAULT 'CURRENT',created_at timestamptz NOT NULL,FOREIGN KEY(scope_id,incident_id,revision) REFERENCES ops.incident_revisions(scope_id,incident_id,revision) ON DELETE CASCADE,FOREIGN KEY(scope_id,impact_assessment_id) REFERENCES ops.impact_assessments(scope_id,id),UNIQUE(scope_id,incident_id,plan_version),UNIQUE(scope_id,id));
CREATE TABLE ops.approvals(id uuid PRIMARY KEY,scope_id uuid NOT NULL,plan_id uuid NOT NULL,plan_version integer NOT NULL,plan_hash text NOT NULL,required_role text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','EXPIRED','SUPERSEDED')),expires_at timestamptz NOT NULL,actor_id uuid REFERENCES ops.users(id),decision text,comment text,decided_at timestamptz,FOREIGN KEY(scope_id,plan_id) REFERENCES ops.action_plans(scope_id,id) ON DELETE CASCADE,UNIQUE(scope_id,plan_id,required_role),UNIQUE(scope_id,id));
CREATE TABLE ops.incident_actions(id uuid PRIMARY KEY,scope_id uuid NOT NULL,plan_id uuid NOT NULL,action_key text NOT NULL,action_type text NOT NULL,payload jsonb NOT NULL,required_role text,status text NOT NULL CHECK(status IN ('PLANNED','WAITING_APPROVAL','READY','IN_PROGRESS','SUCCEEDED','RETRY_SCHEDULED','FAILED','UNKNOWN_OUTCOME','CANCELLED')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 4),claim_token uuid,lease_until timestamptz,next_attempt_at timestamptz NOT NULL DEFAULT now(),provider_id text,execution_id text,workflow_id text,result jsonb NOT NULL DEFAULT '{}',FOREIGN KEY(scope_id,plan_id) REFERENCES ops.action_plans(scope_id,id) ON DELETE CASCADE,UNIQUE(scope_id,action_key),UNIQUE(scope_id,id));
CREATE INDEX action_due ON ops.incident_actions(status,next_attempt_at,lease_until);
CREATE TABLE ops.outbox_events(id uuid PRIMARY KEY,scope_id uuid NOT NULL REFERENCES ops.scopes(id),event_key text NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'PENDING',lease_until timestamptz,attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_id,event_key));
CREATE TABLE ops.wait_registrations(scope_id uuid NOT NULL,plan_id uuid NOT NULL,execution_id text NOT NULL,workflow_id text NOT NULL,resume_url text NOT NULL,registered_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope_id,plan_id),FOREIGN KEY(scope_id,plan_id) REFERENCES ops.action_plans(scope_id,id) ON DELETE CASCADE);
CREATE TABLE ops.audit_events(id uuid PRIMARY KEY,scope_id uuid NOT NULL REFERENCES ops.scopes(id),event text NOT NULL,object_id text NOT NULL,actor text NOT NULL,data jsonb NOT NULL,correlation_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_scope_object ON ops.audit_events(scope_id,object_id,created_at);
CREATE TABLE ops.workflow_errors(id uuid PRIMARY KEY,scope_id uuid REFERENCES ops.scopes(id),job_id uuid,execution_id text,workflow_id text,error_class text NOT NULL,message text NOT NULL,retryable boolean NOT NULL,dead_letter boolean NOT NULL DEFAULT false,next_attempt_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(scope_id,job_id) REFERENCES ops.analysis_jobs(scope_id,id) ON DELETE CASCADE);
CREATE TABLE ops.provider_receipts(id uuid PRIMARY KEY,scope_id uuid NOT NULL,action_id uuid NOT NULL,provider text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(scope_id,action_id) REFERENCES ops.incident_actions(scope_id,id) ON DELETE CASCADE,UNIQUE(scope_id,action_id));
CREATE TABLE ops.digests(id uuid PRIMARY KEY,scope_id uuid NOT NULL REFERENCES ops.scopes(id),business_date date NOT NULL,channel text NOT NULL,body jsonb NOT NULL,UNIQUE(scope_id,business_date,channel));
CREATE TABLE ops.failures(scope_id uuid NOT NULL REFERENCES ops.scopes(id),kind text NOT NULL,enabled boolean NOT NULL,PRIMARY KEY(scope_id,kind));
CREATE TABLE ops.evaluation_runs(id uuid PRIMARY KEY,dataset_version text NOT NULL,prompt_version text NOT NULL,model text NOT NULL,provider text NOT NULL,mode text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ops.evaluation_results(run_id uuid REFERENCES ops.evaluation_runs(id),case_id text NOT NULL,split text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(run_id,case_id));

CREATE TABLE erp.suppliers(scope_id uuid NOT NULL REFERENCES ops.scopes(id),id text NOT NULL,name text NOT NULL,PRIMARY KEY(scope_id,id));
CREATE TABLE erp.materials(scope_id uuid NOT NULL REFERENCES ops.scopes(id),id text NOT NULL,description text NOT NULL,unit text NOT NULL,material_type text NOT NULL,PRIMARY KEY(scope_id,id));
CREATE TABLE erp.supplier_materials(scope_id uuid NOT NULL,supplier_id text NOT NULL,material_id text NOT NULL,qualified boolean NOT NULL,available_at timestamptz,PRIMARY KEY(scope_id,supplier_id,material_id),FOREIGN KEY(scope_id,supplier_id) REFERENCES erp.suppliers(scope_id,id),FOREIGN KEY(scope_id,material_id) REFERENCES erp.materials(scope_id,id));
CREATE TABLE erp.purchase_orders(scope_id uuid NOT NULL,id text NOT NULL,supplier_id text NOT NULL,PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,supplier_id) REFERENCES erp.suppliers(scope_id,id));
CREATE TABLE erp.purchase_order_items(scope_id uuid NOT NULL,id text NOT NULL,purchase_order_id text NOT NULL,material_id text NOT NULL,ordered_quantity numeric(18,4) NOT NULL CHECK(ordered_quantity>=0),open_quantity numeric(18,4) NOT NULL CHECK(open_quantity>=0 AND open_quantity<=ordered_quantity),PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,purchase_order_id) REFERENCES erp.purchase_orders(scope_id,id),FOREIGN KEY(scope_id,material_id) REFERENCES erp.materials(scope_id,id));
CREATE TABLE erp.supply_schedules(scope_id uuid NOT NULL,id text NOT NULL,purchase_order_item_id text NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),available_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('CONFIRMED','PROPOSED')),revision integer NOT NULL,PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,purchase_order_item_id) REFERENCES erp.purchase_order_items(scope_id,id));
CREATE TABLE erp.inventory_lots(scope_id uuid NOT NULL,id text NOT NULL,material_id text NOT NULL,site text NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>=0),quality_status text NOT NULL,PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,material_id) REFERENCES erp.materials(scope_id,id));
CREATE TABLE erp.production_orders(scope_id uuid NOT NULL,id text NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>=0),priority integer NOT NULL,PRIMARY KEY(scope_id,id));
CREATE TABLE erp.inventory_reservations(scope_id uuid NOT NULL,id text NOT NULL,lot_id text NOT NULL,production_order_id text NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,lot_id) REFERENCES erp.inventory_lots(scope_id,id),FOREIGN KEY(scope_id,production_order_id) REFERENCES erp.production_orders(scope_id,id));
CREATE TABLE erp.production_requirements(scope_id uuid NOT NULL,id text NOT NULL,production_order_id text NOT NULL,material_id text NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),need_at timestamptz NOT NULL,remaining_days numeric(10,4) NOT NULL,PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,production_order_id) REFERENCES erp.production_orders(scope_id,id),FOREIGN KEY(scope_id,material_id) REFERENCES erp.materials(scope_id,id));
CREATE TABLE erp.machines(scope_id uuid NOT NULL,id text NOT NULL,site text NOT NULL,PRIMARY KEY(scope_id,id));
CREATE TABLE erp.machine_capabilities(scope_id uuid NOT NULL,machine_id text NOT NULL,capability text NOT NULL,PRIMARY KEY(scope_id,machine_id,capability),FOREIGN KEY(scope_id,machine_id) REFERENCES erp.machines(scope_id,id));
CREATE TABLE erp.capacity_calendar(scope_id uuid NOT NULL,id text NOT NULL,machine_id text NOT NULL,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,available_hours numeric(18,4) NOT NULL CHECK(available_hours>=0),PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,machine_id) REFERENCES erp.machines(scope_id,id),CHECK(end_at>start_at));
CREATE TABLE erp.production_operations(scope_id uuid NOT NULL,id text NOT NULL,production_order_id text NOT NULL,machine_id text NOT NULL,site text NOT NULL,required_capability text NOT NULL,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,required_hours numeric(18,4) NOT NULL CHECK(required_hours>0),PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,production_order_id) REFERENCES erp.production_orders(scope_id,id),FOREIGN KEY(scope_id,machine_id) REFERENCES erp.machines(scope_id,id),CHECK(end_at>start_at));
CREATE TABLE erp.customers(scope_id uuid NOT NULL,id text NOT NULL,strategic boolean NOT NULL,PRIMARY KEY(scope_id,id));
CREATE TABLE erp.sales_orders(scope_id uuid NOT NULL,id text NOT NULL,customer_id text NOT NULL,PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,customer_id) REFERENCES erp.customers(scope_id,id));
CREATE TABLE erp.sales_order_items(scope_id uuid NOT NULL,id text NOT NULL,sales_order_id text NOT NULL,open_quantity numeric(18,4) NOT NULL CHECK(open_quantity>=0),open_net_line_value_cents bigint NOT NULL CHECK(open_net_line_value_cents>=0),customer_due_at timestamptz NOT NULL,PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,sales_order_id) REFERENCES erp.sales_orders(scope_id,id));
CREATE TABLE erp.production_sales_allocations(scope_id uuid NOT NULL,production_order_id text NOT NULL,sales_line_id text NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),PRIMARY KEY(scope_id,production_order_id,sales_line_id),FOREIGN KEY(scope_id,production_order_id) REFERENCES erp.production_orders(scope_id,id),FOREIGN KEY(scope_id,sales_line_id) REFERENCES erp.sales_order_items(scope_id,id));
CREATE TABLE erp.shipments(scope_id uuid NOT NULL,id text NOT NULL,status text NOT NULL,planned_at timestamptz NOT NULL,PRIMARY KEY(scope_id,id));
CREATE TABLE erp.shipment_items(scope_id uuid NOT NULL,id text NOT NULL,shipment_id text NOT NULL,sales_line_id text NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),status text NOT NULL,PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,shipment_id) REFERENCES erp.shipments(scope_id,id),FOREIGN KEY(scope_id,sales_line_id) REFERENCES erp.sales_order_items(scope_id,id));
CREATE TABLE erp.lot_allocations(scope_id uuid NOT NULL,lot_id text NOT NULL,shipment_item_id text NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),PRIMARY KEY(scope_id,lot_id,shipment_item_id),FOREIGN KEY(scope_id,lot_id) REFERENCES erp.inventory_lots(scope_id,id),FOREIGN KEY(scope_id,shipment_item_id) REFERENCES erp.shipment_items(scope_id,id));
CREATE TABLE erp.quality_inspections(scope_id uuid NOT NULL,id text NOT NULL,lot_id text NOT NULL,result text NOT NULL,verified boolean NOT NULL,evidence text NOT NULL,PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,lot_id) REFERENCES erp.inventory_lots(scope_id,id));
CREATE TABLE erp.command_receipts(scope_id uuid NOT NULL,action_id uuid NOT NULL,command text NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(scope_id,action_id),FOREIGN KEY(scope_id,action_id) REFERENCES ops.incident_actions(scope_id,id) ON DELETE CASCADE);
CREATE TABLE erp.fixture_data(scope_id uuid NOT NULL REFERENCES ops.scopes(id),incident_type text NOT NULL,body jsonb NOT NULL,PRIMARY KEY(scope_id,incident_type));

-- Serialization constraints: schedule and inventory aggregates cannot overcommit.
CREATE FUNCTION erp.check_schedule() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE maximum numeric; committed numeric;
BEGIN
 SELECT open_quantity INTO maximum FROM erp.purchase_order_items WHERE scope_id=NEW.scope_id AND id=NEW.purchase_order_item_id FOR UPDATE;
 SELECT COALESCE(sum(quantity),0) INTO committed FROM erp.supply_schedules WHERE scope_id=NEW.scope_id AND purchase_order_item_id=NEW.purchase_order_item_id AND revision=NEW.revision AND status='CONFIRMED';
 IF committed>maximum THEN RAISE EXCEPTION 'confirmed schedule exceeds open purchase quantity' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER supply_total AFTER INSERT OR UPDATE ON erp.supply_schedules DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION erp.check_schedule();
CREATE FUNCTION ops.reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record'; END $$;
CREATE TRIGGER immutable_snapshot BEFORE UPDATE ON erp.snapshots FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();
CREATE TRIGGER immutable_revision BEFORE UPDATE ON ops.incident_revisions FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();
CREATE TRIGGER immutable_impact BEFORE UPDATE ON ops.impact_assessments FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();
CREATE TRIGGER immutable_risk BEFORE UPDATE ON ops.risk_assessments FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();
CREATE TRIGGER append_only_audit BEFORE UPDATE OR DELETE ON ops.audit_events FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();
